def transform(grid):
    h, w = len(grid), len(grid[0])

    # The colored lattice separators repeat at fixed intervals. Find rows
    # and columns that are almost entirely one divider color, and sample
    # their intersections, excluding the initial top/left frame.
    from collections import Counter

    row_candidates = []
    for r, row in enumerate(grid):
        if max(Counter(row).values()) >= w - 3:
            row_candidates.append(r)

    col_candidates = []
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if max(Counter(vals).values()) >= h - 3:
            col_candidates.append(c)

    # Keep the regularly spaced separator positions.
    def spaced(pos):
        if len(pos) < 2:
            return pos
        diffs = [b - a for a, b in zip(pos, pos[1:])]
        step = Counter(diffs).most_common(1)[0][0]
        return [p for p in pos if (p - pos[0]) % step == 0]

    rows = spaced(row_candidates)
    cols = spaced(col_candidates)

    # Remove the plain outer frame when present.
    if len(rows) > 1:
        rows = rows[1:]
    if len(cols) > 1:
        cols = cols[1:]

    return [[grid[r][c] for c in cols] for r in rows]
